def compute(vars):
    old_berths = vars["v1"]
    additional_berths = vars["v2"]
    if old_berths == 0:
        return None

    new_berths = old_berths + additional_berths
    change_ratio = (new_berths - old_berths) / old_berths
    percentage_increase = change_ratio * 100

    return {
        "value": percentage_increase,
        "trace": {
            "old_berths": old_berths,
            "additional_berths": additional_berths,
            "new_berths": new_berths,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
